package greeter

import "strings"

// Slug 把名字转成 URL 友好的锚点 slug：
// 大小写不敏感（统一小写）、空白折叠成连字符、首尾不留连字符。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want string
	}{
		{"lowercases", "Ada Lovelace", "ada-lovelace"},
		{"trims edges", "  Ada Lovelace  ", "ada-lovelace"},
		{"folds whitespace runs", "a   b", "a-b"},
		{"handles tabs and newlines", "Foo\tBar\nBaz", "foo-bar-baz"},
		{"already a slug", "abc-123", "abc-123"},
		{"empty stays empty", "", ""},
		{"blank stays empty", " \t\n ", ""},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("%s: Slug(%q) = %q, want %q", c.name, c.in, got, c.want)
		}
	}
}
